"""Full performed forms from licensed solo-guitar editions; original MIDI voices retained."""
import argparse,hashlib,json,re,subprocess,tempfile
from pathlib import Path
from import_bwv1012 import read_notes
from import_repertoire_batch4 import VOICE_MIDI
ROOT=Path(__file__).resolve().parents[1];SOURCES=ROOT/'scripts/score-sources/repertoire-batch6'
PIECES=[
 dict(key='tarrega_adelita',file='adelita',path='TarregaF/adelita',title='Francisco Tárrega · Adelita — Lento',option='Adelita（アデリータ） · レント（反復・D.C.あり）',bpm=70,meter=[3,4],writtenBars=16,beats=120,sourceId=808,credit='Francisco Tárrega / Stewart Holmes / Mutopia (2006)',license='CC BY-SA 2.5',licenseUrl='https://creativecommons.org/licenses/by-sa/2.5/',form=[[0,24],[0,24],[24,48],[24,48],[0,24]],formName='A A B B A: both repeat signs; D.C. al Fine returns through bar8 without repeating A again.'),
 dict(key='aguado3_1',file='aguado-op03n01',path='AguadoD/O3/aguado-op03n01',title='Dionisio Aguado · Op.3 No.1 — Valse',option='Op.3 第1番 · Valse（ワルツ）（反復・D.C.あり）',bpm=90,meter=[3,8],writtenBars=48,beats=168,sourceId=2041,credit='Dionisio Aguado / Glen Larsen / Mutopia (2016)',license='CC BY-SA 4.0',licenseUrl='https://creativecommons.org/licenses/by-sa/4.0/',form=[[0,12],[0,12],[12,24],[12,24],[24,48],[24,48],[48,72],[48,72],[0,24]],formName='A A B B C C D D A B: four volta sections; D.C. returns through Fine at bar16 with return repeats omitted.'),
 dict(key='carcassi60_2',file='carcassi-op60-02',path='CarcassiM/O60/carcassi-op60-02',title='Matteo Carcassi · Op.60 No.2 — Moderato con espressivo',option='Op.60 第2番 · モデラート（後半反復あり）',bpm=100,meter=[4,4],writtenBars=24,beats=160,sourceId=1853,credit='Matteo Carcassi / Glen Larsen / Mutopia (2013)',license='CC BY-SA 3.0',licenseUrl='https://creativecommons.org/licenses/by-sa/3.0/',form=[[0,32],[32,96],[32,96]],formName='A B B: eight-bar opening, then sixteen-bar second section repeated.')
]
def expand(raw,form):
 result=[];offset=0
 for start,end in form:
  section=[e for e in raw if start<=e[0]<end]
  if not section or any(a+d>end+1e-8 for a,p,d in section):raise ValueError('Section boundary cuts a source note')
  result.extend([[offset+(a-start),p,d] for a,p,d in section]);offset+=end-start
 return result,offset

def compile_midi(executable):
 with tempfile.TemporaryDirectory() as directory:
  for p in PIECES:
   original=SOURCES/(p['file']+'.ly');text=subprocess.run([str(Path(executable).with_name('convert-ly')),str(original)],capture_output=True,text=True,check=True).stdout
   text,n=re.subn(r'\\midi\s*\{',lambda _: '\\midi { '+VOICE_MIDI,text);assert n==1
   tmp=Path(directory)/(p['file']+'.ly');tmp.write_text(text)
   subprocess.run([executable,'-dno-print-pages','-dbackend=null','-o',str(SOURCES/p['file']),str(tmp)],check=True)

def build():
 songs,manifest={},[]
 for p in PIECES:
  raw=read_notes((SOURCES/(p['file']+'.midi')).read_bytes());events,end=expand(raw,p['form']);assert end==p['beats']
  source={k:p[k] for k in ['credit','license','licenseUrl']};source.update(url=f"https://www.mutopiaproject.org/cgibin/piece-info.cgi?id={p['sourceId']}",modifications='Official convert-ly and LilyPond 2.24.4, separate MIDI voices; all overlaps/grace timing retained. '+p['formName']+' Source MIDI tempo used as fixed audition tempo; expressive timing not modeled. No pitch shift. App articulation separate.',pitch='Original guitar sounding pitches, MIDI shift 0; no scordatura or physical settings applied. Not a verified string-choice or fingering simulation.',terms='Derived score data: '+p['license']+'; retain attribution, license and modification notice; share adaptations under the same license. Application code separate.',endingStatus='終端確認済み（反復・戻りと最後の休符を含む）。')
  assert all(len(v)<=500 for v in source.values())
  songs[p['key']]=dict(score=dict(title=p['title'],bpm=p['bpm'],meter=p['meter'],endBeat=end,events=events),label=p['title'],option=p['option'],edition='全曲・反復'+('・D.C.あり' if p['key']!='carcassi60_2' else 'あり')+'・ギター実音',source=source)
  manifest.append({**p,'source':source,'rawNotes':len(raw),'notes':len(events),'noteEndBeats':max(a+d for a,p,d in events),'pitchRange':[min(e[1] for e in events),max(e[1] for e in events)],'performedBars':end/(p['meter'][0]*4/p['meter'][1]),'lilypondUrl':'https://raw.githubusercontent.com/MutopiaProject/MutopiaProject/master/ftp/'+p['path']+'/'+p['file']+'.ly','sha256':{p['file']+ext:hashlib.sha256((SOURCES/(p['file']+ext)).read_bytes()).hexdigest() for ext in ['.ly','.midi']}})
 (ROOT/'synth-demo/repertoire-batch6.js').write_text('// Generated by import_repertoire_batch6.py. Score data CC BY-SA 2.5/4.0/3.0 as individually attributed; application code separate.\nconst repertoireBatch6 = '+json.dumps(songs,ensure_ascii=False,separators=(',',':')).replace('],[','],\n[')+';\n')
 (SOURCES/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print([(m['key'],m['notes'],m['beats'],m['pitchRange']) for m in manifest])
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--lilypond');args=parser.parse_args()
 if args.lilypond:compile_midi(args.lilypond)
 build()
